        ("11 · Hacia el sureste", "Kubu → Mmatshumo → Letlhakane → Orapa → Serowe", "~400 km · 2 días"),
        ("12 · Rinocerontes e historia", "Khama Rhino Sanctuary → Serowe (Khama III Museum) → Palapye", "~80 km · 2 días"),
        ("13 · El Limpopo", "Palapye → Tuli Block / Northern Tuli Game Reserve", "~250 km · 2-3 días"),
        ("14 · Salida", "Tuli → Martin's Drift / Groblersbrug (Sudáfrica)", "~140 km · 1 día"),
